Q: Player not jumping. Unity RigidBody2D A: <pre><code>using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerMove : MonoBehaviour
{
    private Rigidbody rb;
    public float moveSpeed = 10f;
    public LayerMask ground;
    public bool isGrounded;
    public float jumpForce = 5f;

    void Start()
    {
        rb = GetComponent&lt;Rigidbody&gt;();
    }

    void Update()
    {
        // input
        float x = Input.GetAxisRaw(&quot;Horizontal&quot;) *moveSpeed;
        float y = Input.GetAxisRaw(&quot;Vertical&quot;) * moveSpeed;

        //Check ground
        isGrounded = Physics.CheckSphere(new Vector3(transform.position.x, transform.position.y - 1, transform.position.z), 0.4f, ground);

        //jumping
        if (Input.GetKeyDown(KeyCode.Space) &amp;&amp; isGrounded) {
            rb.velocity = new Vector3(rb.velocity.x, jumpForce, rb.velocity.z);
            Debug.Log(isGrounded);
        }

        // moving
        Vector3 movePos = transform.right*x+ transform.forward*y;
        Vector3 newMovePos = new Vector3(movePos.x, rb.velocity.y, movePos.z);

        rb.velocity = newMovePos;

    }
}
</code></pre>

Q: Deleting a Standard TCP IP port using xcvdata not working A: <p>Win11 22631.6494</p>
<p>VS:18.2.1</p>
<p>Reference:</p>
<p><a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/tcpxcv/ns-tcpxcv-_delete_port_data_1" rel="nofollow noreferrer">https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/tcpxcv/ns-tcpxcv-_delete_port_data_1</a></p>
<p>For me the &quot;solution&quot; was this:</p>
<pre><code>bool DeletePortXcv(const std::wstring &amp;portName) {
    HANDLE hPrinter = NULL;

    PRINTER_DEFAULTS PrinterDefaults;
    memset(&amp;PrinterDefaults, 0, sizeof(PrinterDefaults));

    PrinterDefaults.pDatatype = NULL;
    PrinterDefaults.pDevMode = NULL;
    //SERVER_ACCESS_ADMINISTER !!!
    PrinterDefaults.DesiredAccess = SERVER_ACCESS_ADMINISTER;

    DWORD errorCode = NULL;

    LPSTR messageBuffer = nullptr;

    size_t size = 0;

    /* same as create monitor*/
    wchar_t monitorName[] = L&quot;,XcvMonitor Standard TCP/IP Port&quot;;
    if(!OpenPrinter(monitorName, &amp;hPrinter, &amp;PrinterDefaults)){
        errorCode = GetLastError();

        messageBuffer = nullptr;

        /* format error*/
        size = FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS, NULL, errorCode, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT), (LPSTR)&amp;messageBuffer, 0, NULL);

        if(size &gt; 0){
            std::cout &lt;&lt; &quot;Error at OpenPrinterW (monitor open) (&quot; &lt;&lt; errorCode &lt;&lt; &quot;): &quot; &lt;&lt; messageBuffer &lt;&lt; std::endl;
        }
        return false;
    }


    DELETE_PORT_DATA_1 pd; /*USE DELETE_PORT_DATA_1 insted of PORT_DATA_1, DO NOT USE:PORT_DATA_1*/
    memset(&amp;pd, 0, sizeof(pd));

    pd.dwVersion = 1;                 /*MUST: 1*/

    wcscpy_s(pd.psztPortName, MAX_PORTNAME_LEN, portName.c_str());

    DWORD dwStatus = 0;
    DWORD cbOutputNeeded = 0;
    DWORD dwXcvResult = 0;
    /*_DELETE_PORT_DATA_1*/
    /* port name string*/
    /* use this:sizeof(DELETE_PORT_DATA_1)*/
    BOOL bRes = XcvData(
        hPrinter,
        L&quot;DeletePort&quot;,
        (BYTE*)&amp;pd,
        sizeof(DELETE_PORT_DATA_1),
        NULL,
        0,
        &amp;cbOutputNeeded,
        &amp;dwXcvResult
    );

    errorCode = GetLastError();

    messageBuffer = nullptr;

    /* error formating*/
    size = FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS, NULL, errorCode, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT), (LPSTR)&amp;messageBuffer, 0, NULL);

    if(size &gt; 0){
        std::cout &lt;&lt; &quot;Error at XcvData (DeletePort) (&quot; &lt;&lt; errorCode &lt;&lt; &quot;): &quot; &lt;&lt; messageBuffer &lt;&lt; std::endl;
    }

    ClosePrinter(hPrinter);

    /* ERROR_SUCCESS*/
    return (bRes &amp;&amp; dwXcvResult == ERROR_SUCCESS);
}
</code></pre>

Q: How to get notified about changes of the history via history.pushState? A: <p>The new Navigation API (<a href="https://html.spec.whatwg.org/multipage/nav-history-apis.html#navigation-api" rel="nofollow noreferrer">WhatWG spec</a> / <a href="https://developer.chrome.com/docs/web-platform/navigation-api" rel="nofollow noreferrer">Chrome dev page</a> / <a href="https://developer.mozilla.org/en-US/docs/Web/API/Navigation/navigate_event" rel="nofollow noreferrer">MDN page</a>) fixes this by providing another way to watch for navigation changes:</p>
<pre class="lang-ts prettyprint-override"><code>navigation.addEventListener('navigate', (e) =&gt; {
  // do stuff
})
</code></pre>
<p>This is triggered on both <code>pushState</code> and <code>replaceState</code> calls. You can check <code>e.navigationType</code> to filter the events. It's possible values are <code>reload</code>, <code>push</code>, <code>replace</code> and <code>traverse</code>.</p>
<p>It hit Baseline 2026 as of January 2026 (<a href="https://caniuse.com/mdn-api_navigation" rel="nofollow noreferrer">caniuse</a> / <a href="https://developer.mozilla.org/en-US/docs/Web/API/Navigation/navigate_event" rel="nofollow noreferrer">MDN</a>). It works in Chrome, Edge, Safari, Firefox, Opera, Chrome for Android, Safari on iOS, and more.</p>

Q: How to add doc comments for variables that contain React hook return values? A: <p>You can document the inner function that is returned.</p>
<pre class="lang-js prettyprint-override"><code>function useFrobnaticator() {
  /**
   * Frobnicate a string value.
   * 
   * @param stringToFrobnicate (string) - A string value to frobnicate
   */
  return (stringToFrobnicate: string) =&gt; {
    console.log(
      stringToFrobnicate.length &gt; 20 ? &quot;(too long)&quot; : stringToFrobnicate
    );
  };
}
</code></pre>
<p>I don't have PyCharm but this appears to work for VSCode and Intellisense-based IDEs.</p>
